; frame.asm -- chapter 12: three numbers passed on the stack
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "frame.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
result  EQU RAM_START          ; the sum, for the debugger
; Three numbers passed to a routine on the stack, read there through IX, and
; taken off again by the caller.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        ld hl, 1000
        push hl
        ld hl, 2000
        push hl
        ld hl, 3000
        push hl
f1:     call sum3               ; HL: the sum of the three
f2:     pop de                  ; the caller takes them off again
        pop de
        pop de
f3:     ld (result), hl
stop:   jr stop

; sum3: HL = the sum of the three words pushed before the CALL. Uses IX, DE.
sum3:   ld ix, 0
        add ix, sp              ; IX = SP: the way back is at IX+0
read:   ld l, (ix+2)
        ld h, (ix+3)            ; the last pushed
        ld e, (ix+4)
        ld d, (ix+5)            ; the one before
        add hl, de
        ld e, (ix+6)
        ld d, (ix+7)            ; the first pushed
        add hl, de
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
